-- Errata reading for N35: Adults = age 18+ (latest reported age).
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('immunization_history','immunizations')), h AS (SELECT patient, min(json_extract(payload,'$.event_date')) hd FROM r WHERE stream='immunization_history' AND json_extract(payload,'$.recall') IN ('does_not_recall_tetanus','recalls_tetanus_over_ten_years') GROUP BY 1), t AS (SELECT patient, json_extract(payload,'$.event_date') td FROM r WHERE stream='immunizations' AND json_extract(payload,'$.vaccine')='Tdap' AND json_extract(payload,'$.administration_status')='completed') , ad AS (SELECT p.id patient FROM patients p WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) >= 18) SELECT round(100.0*(SELECT count(*) FROM h WHERE h.patient IN (SELECT patient FROM ad) AND EXISTS (SELECT 1 FROM t WHERE t.patient=h.patient AND t.td>=h.hd))/(SELECT count(*) FROM h WHERE h.patient IN (SELECT patient FROM ad)),1) AS value;
